import { Module } from '@nestjs/common';
import { ConfigModule, ConfigService } from '@nestjs/config';
import { TypeOrmModule } from '@nestjs/typeorm';
import { resolve } from 'node:path';
import { ContactModule } from './modules/contact/contact.module';
import { CompanyModule } from './modules/company/company.module';
import { DealModule } from './modules/deal/deal.module';

const nodeEnv = process.env.NODE_ENV ?? 'development';
const defaultSynchronize = nodeEnv === 'production' ? 'false' : 'true';

@Module({
  imports: [
    ConfigModule.forRoot({
      isGlobal: true,
      envFilePath: [
        resolve(process.cwd(), `../.env.${nodeEnv}`),
        resolve(process.cwd(), '../.env'),
        resolve(process.cwd(), `.env.${nodeEnv}`),
        resolve(process.cwd(), '.env'),
      ],
    }),
    TypeOrmModule.forRootAsync({
      inject: [ConfigService],
      useFactory: (configService: ConfigService) => ({
        type: 'postgres',
        host: configService.get<string>('DB_HOST', 'localhost'),
        port: Number(configService.get<string>('DB_PORT', '5432')),
        username: configService.get<string>('DB_USERNAME', 'postgres'),
        password: configService.get<string>('DB_PASSWORD', 'postgres'),
        database: configService.get<string>('DB_DATABASE', 'crm_baseline'),
        autoLoadEntities: true,
        synchronize:
          configService.get<string>('DB_SYNCHRONIZE', defaultSynchronize) ===
          'true',
      }),
    }),
    CompanyModule,
    ContactModule,
    DealModule,
  ],
})
export class AppModule {}

export const DEAL_STAGES = [
  'lead',
  'qualified',
  'active',
  'negotiation',
  'closed_won',
  'closed_lost',
] as const;

export type DealStage = (typeof DEAL_STAGES)[number];

export const DEAL_INITIAL_STAGES = ['lead', 'qualified'] as const;

export const DEAL_STAGE_TRANSITIONS: Record<DealStage, DealStage[]> = {
  lead: ['qualified', 'closed_lost'],
  qualified: ['active', 'closed_lost'],
  active: ['negotiation', 'closed_lost'],
  negotiation: ['closed_won', 'closed_lost'],
  closed_won: [],
  closed_lost: ['lead'],
};

const DEAL_STAGE_SET = new Set<string>(DEAL_STAGES);

export function isDealStage(stage: string): stage is DealStage {
  return DEAL_STAGE_SET.has(stage);
}
