import {
  Column,
  CreateDateColumn,
  DeleteDateColumn,
  Entity,
  PrimaryGeneratedColumn,
  UpdateDateColumn,
} from 'typeorm';

@Entity('deals')
export class DealEntity {
  @PrimaryGeneratedColumn('uuid')
  id!: string;

  @Column({ type: 'uuid' })
  companyId!: string;

  @Column({ type: 'uuid', nullable: true })
  primaryContactId!: string | null;

  @Column({ type: 'varchar', length: 255, comment: 'Deal name' })
  name!: string;

  @Column({ type: 'double precision', comment: 'Deal value amount' })
  value!: number;

  @Column({
    type: 'varchar',
    length: 100,
    default: 'lead',
    comment: 'Deal stage in sales pipeline',
  })
  stage!: string;

  @Column({
    type: 'timestamptz',
    nullable: true,
    comment: 'Expected close date',
  })
  expectedCloseDate!: Date | null;

  @CreateDateColumn({ type: 'timestamptz', comment: 'Creation timestamp' })
  createdAt!: Date;

  @UpdateDateColumn({ type: 'timestamptz', comment: 'Update timestamp' })
  updatedAt!: Date;

  @DeleteDateColumn({
    type: 'timestamptz',
    nullable: true,
    select: false,
    comment: 'Soft delete timestamp',
  })
  deletedAt!: Date;
}
