import {
  Column,
  CreateDateColumn,
  Entity,
  Index,
  PrimaryColumn,
  UpdateDateColumn,
} from 'typeorm';

@Entity('deal_contacts')
@Index('idx_deal_contacts_contact_id', ['contactId'])
@Index('idx_deal_contacts_deal_id', ['dealId'])
export class DealContactLinkEntity {
  @PrimaryColumn({ type: 'uuid' })
  dealId!: string;

  @PrimaryColumn({ type: 'uuid' })
  contactId!: string;

  @Column({ type: 'varchar', length: 100, nullable: true })
  role!: string | null;

  @CreateDateColumn({ type: 'timestamptz' })
