490	  } {
491	    const currentNormalizedLinks = currentLinks.map((link) => ({
492	      contactId: link.contactId,
493	      role: link.role,
494	    }));
495	
496	    const hasContactLinks = Object.prototype.hasOwnProperty.call(
497	      dto,
498	      'contactLinks',
499	    );
500	    const hasPrimaryContactId = Object.prototype.hasOwnProperty.call(
501	      dto,
502	      'primaryContactId',
503	    );
504	
505	    const nextLinks = hasContactLinks
506	      ? this.normalizeContactLinks(dto.contactLinks ?? [], 'contactLinks')
507	      : currentNormalizedLinks;
508	
509	    let nextPrimaryContactId = currentPrimaryContactId;
510	
511	    if (hasPrimaryContactId) {
512	      nextPrimaryContactId = dto.primaryContactId ?? null;
513	    }
514	
515	    if (hasContactLinks && !hasPrimaryContactId) {
516	      const nextLinkIds = new Set(nextLinks.map((link) => link.contactId));
517	      if (!nextPrimaryContactId || !nextLinkIds.has(nextPrimaryContactId)) {
518	        nextPrimaryContactId = null;
