758	function findFirstDuplicate(values: string[]): string | null {
759	  const seenValues = new Set<string>();
760	
761	  for (const value of values) {
762	    if (seenValues.has(value)) {
763	      return value;
764	    }
765	
766	    seenValues.add(value);
767	  }
768	
769	  return null;
770	}
