    44	export async function listConstraintNames(
    45	  dataSource: DataSource,
    46	  tableName: string,
    47	): Promise<string[]> {
    48	  const rows = await dataSource.query(
    49	    `
    50	      SELECT conname
    51	      FROM pg_constraint
    52	      WHERE conrelid = $1::regclass
    53	      ORDER BY conname
    54	    `,
    55	    [tableName],
    56	  );
    57	
    58	  return rows.map((row: { conname: string }) => row.conname);
    59	}
    60	
    61	export async function listIndexNames(
    62	  dataSource: DataSource,
    63	  tableName: string,
    64	): Promise<string[]> {
    65	  const rows = await dataSource.query(
    66	    `
    67	      SELECT indexname
    68	      FROM pg_indexes
    69	      WHERE schemaname = 'public' AND tablename = $1
    70	      ORDER BY indexname
    71	    `,
    72	    [tableName],
    73	  );
    74	
    75	  return rows.map((row: { indexname: string }) => row.indexname);
