   446	async function hasColumn(
   447	  dataSource: DataSource,
   448	  tableName: string,
   449	  columnName: string,
   450	): Promise<boolean> {
   451	  const [row] = await dataSource.query(
   452	    `
   453	      SELECT EXISTS (
   454	        SELECT 1
   455	        FROM information_schema.columns
   456	        WHERE table_schema = 'public'
   457	          AND table_name = $1
   458	          AND column_name = $2
   459	      ) AS "exists"
   460	    `,
   461	    [tableName, columnName],
   462	  );
   463	
   464	  return Boolean(row?.exists);
   465	}
   466	
   467	async function hasTable(
   468	  dataSource: DataSource,
   469	  tableName: string,
   470	): Promise<boolean> {
   471	  const [row] = await dataSource.query(
   472	    `
   473	      SELECT EXISTS (
   474	        SELECT 1
   475	        FROM information_schema.tables
   476	        WHERE table_schema = 'public'
   477	          AND table_name = $1
   478	      ) AS "exists"
   479	    `,
   480	    [tableName],
   481	  );
   482	
   483	  return Boolean(row?.exists);
   484	}
