   486	async function undoAppliedMigrations(
   487	  dataSource: DataSource,
   488	  count: number,
   489	): Promise<void> {
   490	  for (let migrationIndex = 0; migrationIndex < count; migrationIndex += 1) {
   491	    await dataSource.undoLastMigration();
   492	  }
   493	}

