    13	export const distributeRecentDate = (
    14	  now: Date,
    15	  index: number,
    16	  total: number,
    17	) => {
    18	  const safeTotal = Math.max(total - 1, 1);
    19	  const offsetDays = Math.round((index / safeTotal) * 29);
    20	  const date = daysAgo(now, offsetDays);
    21	
