    48	        .join(' OR '),
    49	      Object.fromEntries(
    50	        prefixes.map((prefix, index) => [`prefix${index}`, `${prefix}%`]),
    51	      ),
    52	    )
    53	    .getRawMany<{ id: string }>();
    54	
