     2	import { Injectable } from '@nestjs/common';
     3	import { Brackets, DataSource } from 'typeorm';
     4	import { CompanyEntity } from './company.entity';
     5	import { CompanyListQueryDto } from './dto';
     6	import { BaseRepository } from '../../core/database/base.repository';
     7	import {
     8	  buildPaginatedResult,
     9	  resolvePagination,
    10	} from '../../common/utils/pagination.util';
    11	
    12	@Injectable()
    13	export class CompanyRepository extends BaseRepository<CompanyEntity> {
    14	  constructor(dataSource: DataSource) {
    15	    super(CompanyEntity, dataSource.createEntityManager());
    16	  }
    17	
    18	  async findWithFilter(query: CompanyListQueryDto) {
    19	    const { page, pageSize, skip, take } = resolvePagination({
    20	      page: query.page,
    21	      pageSize: query.pageSize,
    22	    });
    23	
    24	    const queryBuilder = this.createQueryBuilder('company');
    25	    const searchTerm = query.q?.trim();
    26	
    27	    if (searchTerm) {
    28	      queryBuilder.andWhere(
    29	        new Brackets((searchQuery) => {
    30	          searchQuery
    31	            .where('company.name ILIKE :searchTerm')
    32	            .orWhere('company.email ILIKE :searchTerm')
    33	            .orWhere('company.phone ILIKE :searchTerm');
    34	        }),
    35	        { searchTerm: `%${searchTerm}%` },
    36	      );
    37	    }
    38	
    39	    if (query.status) {
    40	      queryBuilder.andWhere('company.status = :status', {
    41	        status: query.status,
    42	      });
    43	    }
    44	
    45	    if (query.industry) {
    46	      queryBuilder.andWhere('company.industry = :industry', {
    47	        industry: query.industry,
    48	      });
    49	    }
    50	
    51	    const [items, total] = await queryBuilder
    52	      .orderBy('company.createdAt', 'DESC')
    53	      .skip(skip)
    54	      .take(take)
    55	      .getManyAndCount();
    56	
    57	    return buildPaginatedResult({
    58	      items,
    59	      total,
    60	      page,
    61	      pageSize,
    62	    });
    63	  }
    64	}

