 1	import type { PaginatedResult } from '../types/paginated-result.type';
 2	
 3	const DEFAULT_PAGE = 1;
 4	const DEFAULT_PAGE_SIZE = 10;
 5	const MAX_PAGE_SIZE = 100;
 6	
 7	export type PaginationQueryInput = {
 8	  page?: number | string;
 9	  pageSize?: number | string;
10	};
11	
12	export function resolvePagination(query: PaginationQueryInput) {
13	  const page = normalizePositiveInteger(query.page, DEFAULT_PAGE);
14	  const pageSize = Math.min(
15	    normalizePositiveInteger(query.pageSize, DEFAULT_PAGE_SIZE),
16	    MAX_PAGE_SIZE,
17	  );
18	
19	  return {
20	    page,
21	    pageSize,
22	    skip: (page - 1) * pageSize,
23	    take: pageSize,
24	  };
25	}
26	
27	export function buildPaginatedResult<TItem>(args: {
28	  items: TItem[];
29	  page: number;
30	  pageSize: number;
31	  total: number;
32	}): PaginatedResult<TItem> {
33	  const { items, page, pageSize, total } = args;
34	
35	  return {
36	    items,
37	    page,
38	    pageSize,
39	    total,
40	    totalPages: total === 0 ? 0 : Math.ceil(total / pageSize),
41	  };
42	}
43	
44	function normalizePositiveInteger(
45	  value: number | string | undefined,
46	  fallback: number,
47	) {
48	  const parsedValue =
49	    typeof value === 'number' ? value : Number.parseInt(value ?? '', 10);
50	
51	  if (!Number.isFinite(parsedValue) || parsedValue < 1) {
52	    return fallback;
53	  }
54	
55	  return parsedValue;
56	}

